#!/usr/bin/env bash
# Claude Statusline v8 — originally generated by the Claude Statusline VS Code extension
# (uninstalled; hand-edited since 2026-10-07 to add the prompt-cache line. Reinstalling
# that extension would overwrite this file. Backup: statusline.sh.bak-2026-10-07)
payload=$(cat)

reset='\033[0m'; bold='\033[1m'; dim='\033[2m'
red='\033[31m'; green='\033[32m'; yellow='\033[33m'
magenta='\033[35m'; cyan='\033[36m'
sep="${dim}│${reset}"

# ── 1. Model ────────────────────────────────────────────────────────────────
model=$(echo "$payload" | jq -r '.model.display_name // .model.id // .model // "Claude"')
part_model="${magenta}${model}${reset}"
effort=$(echo "$payload" | jq -r '.effort.level // empty')
case "$effort" in
  low)    effort_color="$green" ;;
  medium) effort_color="$yellow" ;;
  *)      effort_color="$red" ;;  # high, xhigh, max
esac
[[ -n "$effort" ]] && part_model+="${dim}·${reset}${effort_color}${effort}${reset}"

# ── 2. Context window ───────────────────────────────────────────────────────
ctx_pct=$(echo "$payload" | jq -r '.context_window.used_percentage // 0')
ctx_int=$(printf "%.0f" "$ctx_pct")
# 70/90 thresholds match the context-bar mod's; auto-compaction runs near the top of the window
if   (( ctx_int >= 90 )); then ctx_color="$red"
elif (( ctx_int >= 70 )); then ctx_color="$yellow"
else                           ctx_color="$green"; fi
part_ctx="${ctx_color}C:${ctx_int}%${reset}"
# Session cost so far, API-equivalent (not what a subscription bills); hidden if absent
cost=$(echo "$payload" | jq -r '.cost.total_cost_usd // empty | . * 100 | round / 100 | tostring')
[[ -n "$cost" ]] && part_ctx+="${dim} \$$(printf "%.2f" "$cost")${reset}"

# ── 3. Git branch ───────────────────────────────────────────────────────────
cwd=$(echo "$payload" | jq -r '.workspace.current_dir // .cwd // ""')
[[ -z "$cwd" ]] && cwd="$PWD"
part_git=""
if git -C "$cwd" rev-parse --is-inside-work-tree &>/dev/null; then
  branch=$(git -C "$cwd" symbolic-ref --short HEAD 2>/dev/null \
        || git -C "$cwd" rev-parse --short HEAD 2>/dev/null)
  part_git="${green}${branch}${reset}"
fi

# ── 4 & 5. Rate limits ──────────────────────────────────────────────────────
rate_color() {
  local p; p=$(printf "%.0f" "$1")
  if   (( p >= 80 )); then printf "%s" "$red"
  elif (( p >= 50 )); then printf "%s" "$yellow"
  else                     printf "%s" "$green"; fi
}
r5=$(echo "$payload" | jq -r '.rate_limits.five_hour.used_percentage // 0')
r7=$(echo "$payload" | jq -r '.rate_limits.seven_day.used_percentage // 0')
r5_resets=$(echo "$payload" | jq -r 'if .rate_limits.five_hour.resets_at != null then .rate_limits.five_hour.resets_at else "" end')
r7_resets=$(echo "$payload" | jq -r 'if .rate_limits.seven_day.resets_at != null then .rate_limits.seven_day.resets_at else "" end')
# rate_limits only arrives with a session's first API reply. Until then show the last
# cached reading as "~N%", or 0 for a window that has reset since it was cached.
stale=""
rate_cache="$HOME/.claude/rate-cache.json"
if [[ -z $(echo "$payload" | jq -r '.rate_limits // empty') && -f "$rate_cache" ]]; then
  read -r r5 r5_resets r7 r7_resets < <(jq -r --argjson now "$(date +%s)" '
    def w(p; at): if ((at | tonumber?) // 0) > $now then "\(p) \(at)" else "0 -" end;
    "\(w(.r5; .r5_resets_at)) \(w(.r7; .r7_resets_at))"' "$rate_cache" | tr -d '\r')
  [[ "$r5_resets" == - ]] && r5_resets=""
  [[ "$r7_resets" == - ]] && r7_resets=""
  stale="~"
fi
# Time until reset (resets_at is epoch seconds): 42m, 3h05m, 4d12h
until_reset() {
  [[ "$1" =~ ^[0-9]+$ ]] || return
  local s=$(( $1 - $(date +%s) ))
  (( s <= 0 )) && return
  if   (( s < 3600 ));  then printf " %dm" $(( (s + 59) / 60 ))
  elif (( s < 86400 )); then printf " %dh%02dm" $(( s / 3600 )) $(( s % 3600 / 60 ))
  else                       printf " %dd%dh" $(( s / 86400 )) $(( s % 86400 / 3600 )); fi
}
part_r5="$(rate_color $r5)U:${stale}$(printf "%.0f" $r5)%${reset}${dim}$(until_reset "$r5_resets")${reset}"
part_r7="$(rate_color $r7)W:${stale}$(printf "%.0f" $r7)%${reset}${dim}$(until_reset "$r7_resets")${reset}"

# ── 7. Folder ───────────────────────────────────────────────────────────────
folder=$(basename "$cwd")
part_folder="${bold}${cyan}${folder}${reset}"

# ── 8. Prompt cache (second line) ───────────────────────────────────────────
# From the status line input's prompt_cache (Claude Code >= 2.1.251). Replaces the
# cache-clock mod, which wrapped this script via a settings.json rewrite (held 2026-10-07).
pc=$(echo "$payload" | jq -r 'if (.prompt_cache|type)=="object" then .prompt_cache | [
  (.caching_observed|tostring), (if .expires_at then (.expires_at|floor|tostring) else "" end),
  (.warm|tostring), (.ttl // ""),
  (if .recache_tokens_if_cold then (.recache_tokens_if_cold | if . >= 1000 then "\(./1000|round)k" else tostring end) else "" end),
  ((.last_miss_cause.causes // []) | map(select(type=="string") | gsub("_";" ")) | join(", "))
] | join("\u001f") else "" end' 2>/dev/null)
part_cache=""
if [[ -n "$pc" ]]; then
  IFS=$'\x1f' read -r pc_obs pc_exp pc_warm pc_ttl pc_recache pc_cause <<< "$pc"
  if [[ "$pc_obs" != "false" ]]; then
    left=""; [[ -n "$pc_exp" ]] && left=$(( pc_exp - $(date +%s) ))
    if [[ "$pc_warm" != "false" && -n "$left" ]] && (( left > 0 )); then
      case "$pc_ttl" in 5m) ttl=300;; 1h) ttl=3600;; *) ttl=0;; esac
      col="$green"; (( ttl > 0 && left * 5 < ttl )) && col="$yellow"
      if (( left >= 60 )); then head="Cache:$(( left / 60 ))m"; else head="Cache:${left}s"; fi
      [[ -n "$pc_ttl" && "$pc_ttl" != "1h" ]] && head+=" ($pc_ttl)"  # 1h is normal; show only an exception (5m = overage)
      part_cache="${col}${head}${reset}"
    else
      part_cache="${red}Cache:cold${reset}"
      [[ -n "$pc_recache" ]] && part_cache+="${dim} · next message re-caches ${pc_recache} tokens${reset}"
      [[ -n "$pc_cause" ]] && part_cache+="${dim} · ${pc_cause}${reset}"
    fi
  fi
fi

# ── Write rate-cache.json for VS Code extension ─────────────────────────────
# Skipped on a cached reading so a fresh session never rewrites live data with stale data.
[[ -z "$stale" ]] && jq -n \
  --argjson r5    "$(printf "%.0f" $r5)" \
  --argjson r7    "$(printf "%.0f" $r7)" \
  --arg     r5at  "$r5_resets" \
  --arg     r7at  "$r7_resets" \
  --argjson ctx   "$ctx_int" \
  --arg     model "$model" \
  --arg     cwd   "$cwd" \
  --argjson ts    "$(date +%s)" \
  '{r5:$r5,r7:$r7,r5_resets_at:$r5at,r7_resets_at:$r7at,context_pct:$ctx,model:$model,cwd:$cwd,ts:$ts}' \
  > "$HOME/.claude/rate-cache.json" 2>/dev/null || true

# ── Assemble and print ──────────────────────────────────────────────────────
line="$part_model${sep}$part_r5${sep}$part_r7${sep}$part_ctx"
[[ -n "$part_cache" ]] && line+="${sep}$part_cache"
line+="${sep}$part_folder"
[[ -n "$part_git" ]] && line+="${sep}$part_git"
printf "%b\n" "$line"
exit 0